async function calcularFrete(rua, numero, bairro) {
  const url = 'URL_DO_WEBHOOK';

  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        rua: rua,
        numero: numero,
        bairro: bairro
      })
    });

    const resultado = await response.json();

    if (resultado.sucesso) {
      console.log(`Frete: R$ ${resultado.valor_frete}`);
      console.log(`Distância: ${resultado.distancia_km} km`);
      return resultado;
    } else {
      console.error('Erro:', resultado.mensagem);
      return null;
    }
  } catch (error) {
    console.error('Erro na requisição:', error);
    return null;
  }
}

// Uso:
calcularFrete('Avenida Doutor Ruy Braga', '123', 'Centro');
